set -euo pipefail
cd /home/ubuntu/apps/travel-planner
cp rag/eval/run_routing_challenge.py /tmp/travel-mixed-stage-20261012/eval/
echo  | base64 -d > /tmp/travel-mixed-stage-20261012/eval/test_mixed_service.py
export PYTHONPATH=/tmp/travel-mixed-stage-20261012:rag
export RAG_SEMANTIC_ROUTING_ENABLED=0 RAG_MIXED_ENABLED=0
.venv/bin/python -m unittest discover -s /tmp/travel-mixed-stage-20261012/eval -p test_*.py -v
export HF_HUB_OFFLINE=1
.venv/bin/python - <<'PY'
import json,os
from pathlib import Path
from retrieval.search_chunks import load_env_files
load_env_files();os.environ['RAG_SEMANTIC_ROUTING_ENABLED']='1'
from service.mixed_service import build_mixed_plan
results=[]
for dataset in ('routing_challenge_v1','answer_holdout_v1'):
    for line in Path('rag/eval/cases/'+dataset+'.jsonl').read_text().splitlines():
        if not line.strip():continue
        c=json.loads(line);p=build_mixed_plan(c['question'])
        expected=dataset=='routing_challenge_v1' and int(c['id'][-2:])>=27
        assert bool(p)==expected,(c['id'],c['question'],p)
        if p:print(json.dumps({'id':c['id'],'ticket':p.ticket_question,'rag':p.rag_question},ensure_ascii=False),flush=True)
        results.append({'id':c['id'],'mixed_plan':bool(p)})
Path('rag/eval/reports/mixed_preflight_v1.json').write_text(json.dumps(results,ensure_ascii=False,indent=2))
print('55 preflight plans matched: only the 4 explicit mixed requests gained two tools')
PY
